let selectedLive=new Set(),selectedSavedCreators=new Set();
let queryState=null;
async function post(path,payload={}){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),x=await r.json();if(!r.ok||x.ok===false)throw new Error(x.error||'请求失败');return x}
function markDataChanged(){try{localStorage.setItem('cdh-data-revision',String(Date.now()))}catch(e){}}
async function refreshCreatorFacts(){if(!interactive)return;const x=await post('/api/creators/facts',{}),arr=x.creators||[];facts.splice(0,facts.length,...arr);byId.clear();arr.forEach(c=>byId.set(c.channel_id,c));window.CDH_CREATOR_FACTS={generated_at:x.generated_at,creators:facts};}
function relationshipCount(c){return Object.entries(c||{}).filter(([k,v])=>k.startsWith('relationship__')&&Number(v||0)).length}
function identity(cid){const c=byId.get(cid);if(!c)return '<span class="pill">尚未入库</span>';const n=relationshipCount(c);return n?`<div class="identity-stack"><span class="pill identity-partnered">Workspace 关系 × ${n}</span></div>`:'<span class="small">—</span>'}
function tierPill(t){const x=String(t||'').toUpperCase(),k={A:'grade-a',B:'grade-b',C:'grade-c',D:'grade-d'}[x]||'';return x?`<span class="pill ${k}">${esc(x)}</span>`:''}
function workflowSelect(c){const cur=c.workflow_status||'unreviewed',opts=[['unreviewed','未处理'],['interested','感兴趣'],['to_contact','待联系'],['added','已入库'],['defer','暂不考虑'],['excluded','永久排除']];return `<select class="select workflow-select" data-workflow="${esc(c.channel_id||'')}">${opts.map(([k,v])=>`<option value="${k}" ${k===cur?'selected':''}>${v}</option>`).join('')}</select>`}
function freshnessBadge(c){const n=Number(c.discovery_run_count||1);return n<=1?'<span class="pill grade-a">首次发现</span>':`<span class="pill grade-b">重复发现 × ${n}</span>`}
function row(c){const cid=c.channel_id||'',id=esc(cid),channelUrl=`https://www.youtube.com/channel/${encodeURIComponent(cid)}`,videoUrl=`https://www.youtube.com/watch?v=${encodeURIComponent(c.video_id||'')}`,coverage=Number(c.query_coverage||0);return `<tr data-cid="${id}"><td><input type="checkbox" class="live-select creator-select" value="${id}" ${selectedLive.has(cid)?'checked':''}></td><td class="entity-cell"><a class="link-ext" target="_blank" rel="noopener" href="${channelUrl}"><b>${esc(c.channel_title||cid)}</b></a>${freshnessBadge(c)}</td><td>${fmt(c.subscribers)}</td><td class="country">${esc(c.country_resolved||c.country_api||'—')}</td><td class="video-title-cell"><a class="link-ext" target="_blank" rel="noopener" href="${videoUrl}" title="${esc(c.title||c.video_id)}">${esc(c.title||c.video_id)}</a>${coverage?`<div class="small">命中 ${coverage} 个 Query</div>`:''}</td><td>${fmt(c.views)}</td><td><b>${c.pre_score==null?'—':Number(c.pre_score).toFixed(1)}</b> ${tierPill(c.opportunity_tier)}</td><td class="identity">${identity(cid)}</td><td>${workflowSelect(c)}<details class="action-menu row-action-menu" style="margin-top:6px"><summary class="btn">操作 ▾</summary><div class="action-menu-panel"><div class="contact"><button class="btn" data-contact="${id}">抓取公开联系方式</button></div><button class="btn" data-add="${id}">仅加入博主库</button><select class="select window"><option value="7">近7天</option><option value="30" selected>近30天</option><option value="60">近60天</option><option value="90">近90天</option><option value="180">近180天</option><option value="365">近365天</option><option value="date_range">指定日期范围</option><option value="full">全历史（最多 ${FULL_HISTORY_LIMIT.toLocaleString('zh-CN')} 条）</option></select><span class="capture-dates" style="display:none"><input class="input fromdate" type="date"><span class="small">至</span><input class="input todate" type="date"></span><button class="btn primary" data-capture="${id}">抓取并入库</button></div></details><div class="small action-status"></div></td></tr>`}
function bindRows(){
 document.querySelectorAll('[data-add]').forEach(b=>b.onclick=async()=>{
   const tr=b.closest('tr'),st=tr.querySelector('.action-status');
   try{st.textContent='正在加入…';await post('/api/add',{channel_id:b.dataset.add});markDataChanged();await refreshCreatorFacts();st.textContent='已加入博主库并开启监控';const cell=tr.querySelector('.identity');if(cell)cell.innerHTML=identity(b.dataset.add);if(interactive)await loadSavedCreator()}
   catch(e){st.textContent=e.message}
 });
 document.querySelectorAll('.window').forEach(sel=>sel.onchange=()=>{const dates=sel.parentElement.querySelector('.capture-dates');if(dates)dates.style.display=sel.value==='date_range'?'inline-flex':'none'});
 document.querySelectorAll('[data-capture]').forEach(b=>b.onclick=async()=>{
   const tr=b.closest('tr'),st=tr.querySelector('.action-status'),sel=tr.querySelector('.window'),from=tr.querySelector('.fromdate').value,to=tr.querySelector('.todate').value;
   try{if(sel.value==='date_range'&&(!from||!to))throw new Error('指定日期范围需要同时填写开始和结束日期');if(sel.value==='date_range'&&from>to)throw new Error('开始日期不能晚于结束日期');st.textContent=sel.value==='full'?`正在抓取全历史（最多 ${FULL_HISTORY_LIMIT.toLocaleString('zh-CN')} 条）…`:'正在抓取视频…';const payload={channel_ids:[b.dataset.capture],window:sel.value,from_date:from,to_date:to};const x=window.CDHJobs?await CDHJobs.run('capture_batch',payload):await post('/api/creators/capture-batch',payload);markDataChanged();await refreshCreatorFacts();st.textContent=`已入库 ${x.videos_processed||0} 条视频；页面数据已刷新`;const cell=tr.querySelector('.identity');if(cell)cell.innerHTML=identity(b.dataset.capture);if(interactive)await loadSavedCreator()}
   catch(e){st.textContent=e.message}
 });
 document.querySelectorAll('.workflow-select').forEach(sel=>sel.onchange=async()=>{if(!interactive)return alert('交互模式下才可保存处理状态');const cid=sel.dataset.workflow;try{await post('/api/workflow/set',{channel_id:cid,status:sel.value});markDataChanged();const c=liveResults.find(x=>x.channel_id===cid);if(c)c.workflow_status=sel.value;renderLive();await loadSavedCreator()}catch(e){alert(e.message)}});
 document.querySelectorAll('[data-contact]').forEach(b=>b.onclick=async()=>{const tr=b.closest('tr'),cell=tr.querySelector('.contact');try{cell.textContent='抓取中…';const x=await post('/api/contact',{channel_id:b.dataset.contact});markDataChanged();await refreshCreatorFacts();cell.innerHTML=`${x.public_email?'<div>'+esc(x.public_email)+'</div>':''}${x.website_url?'<a class="link-ext" target="_blank" rel="noopener" href="'+esc(x.website_url)+'">网站</a> ':''}<span class="small">联系得分 ${fmt(x.contactability_score)} · ${esc(x.contact_status||'')}${x.manual_action_required?' · 邮件需人工验证':''}</span>`;tr.querySelector('.country').innerHTML=esc(x.country_resolved||'—')+'<div class="small">'+esc(x.country_source||'unknown')+'</div>';if(interactive)await loadSavedCreator()}catch(e){cell.textContent=e.message}})
}
function liveSortValue(x,key){if(key==='score')return Number(x.pre_score??-1);if(key==='subs')return Number(x.subscribers||0);if(key==='views')return Number(x.views||0);return x.channel_title||''}
function groupOptions(){return [['','选择区域'],...(GEO.groups||[]).map(x=>[x.id,x.name])]}
function countriesInGroup(group){return group?(GEO.countries||[]).filter(x=>x.group===group).map(x=>[x.code,`${x.name_zh} (${x.code})`]):[]}
function liveFilterOptions(field){if(field==='tier')return ['A','B','C','D'].map(x=>[x,x]);if(field==='identity')return [['has_relationship','存在 Workspace 关系'],['no_relationship','无 Workspace 关系']];return []}
function liveConditionRow(c={},i=0){const d=document.createElement('div');d.className='condition-row';d.innerHTML=(i===0?'<span class="small">起始</span>':'<select class="lf-join"><option>AND</option><option>OR</option><option>NOT</option></select>')+'<select class="lf-field"><option value="geo">地区 / 国家</option><option value="tier">发现分档</option><option value="identity">Workspace 关系</option></select><div class="geo-filter inline"><select class="lf-value"></select><select class="lf-country" style="display:none"></select></div><span></span><span></span><button class="btn danger">×</button>';const f=d.querySelector('.lf-field'),v=d.querySelector('.lf-value'),country=d.querySelector('.lf-country');f.value=c.field||'geo';function fillCountry(selected=''){const arr=countriesInGroup(v.value);country.innerHTML=(v.value?'<option value="">全部该区域</option>':'<option value="">请先选择区域</option>')+arr.map(([k,n])=>`<option value="${k}">${esc(n)}</option>`).join('');if(selected&&arr.some(x=>x[0]===selected))country.value=selected}
function fill(w='',cc=''){if(f.value==='geo'){const o=groupOptions();v.innerHTML=o.map(([k,n])=>`<option value="${k}">${esc(n)}</option>`).join('');if(w&&o.some(x=>x[0]===w))v.value=w;country.style.display='';fillCountry(cc);v.onchange=()=>fillCountry('');return}v.onchange=null;country.style.display='none';const o=liveFilterOptions(f.value);v.innerHTML=o.map(([k,n])=>`<option value="${k}">${esc(n)}</option>`).join('');if(w&&o.some(x=>x[0]===w))v.value=w}fill(c.value||'',c.country||'');f.onchange=()=>fill();if(c.join&&d.querySelector('.lf-join'))d.querySelector('.lf-join').value=c.join;d.querySelector('button').onclick=()=>{d.remove();renumberLive()};return d}
const liveFilterBox=document.getElementById('liveDiscoveryFilters');let liveFilters=[];
function addLive(c={}){liveFilterBox.appendChild(liveConditionRow(c,liveFilterBox.children.length))}
function readLive(){return [...liveFilterBox.children].map((d,i)=>({join:i===0?'':(d.querySelector('.lf-join')?.value||'AND'),field:d.querySelector('.lf-field').value,value:d.querySelector('.lf-value').value,country:d.querySelector('.lf-country')?.value||''})).filter(x=>x.value)}
function renumberLive(){const a=readLive();liveFilterBox.innerHTML='';a.forEach(addLive);if(!a.length)addLive()}
function liveCond(c,x){if(x.field==='geo'){const code=c.country_resolved||c.country_api||'',r=countryByCode.get(code);if(!r||r.group!==x.value)return false;return x.country?code===x.country:true}if(x.field==='tier')return (c.opportunity_tier||'')===x.value;const f=byId.get(c.channel_id),n=relationshipCount(f);if(x.value==='has_relationship')return n>0;if(x.value==='no_relationship')return n===0;return true}
function chain(item,conds,fn){if(!conds.length)return true;let a=fn(item,conds[0]);for(let i=1;i<conds.length;i++){const b=fn(item,conds[i]),j=conds[i].join||'AND';a=j==='OR'?(a||b):j==='NOT'?(a&&!b):(a&&b)}return a}
function discoveryHighlight(tableId,conds,sortKey){const fields=[sortKey,...(conds||[]).map(x=>x.field)];window.CDHTableTools?.highlightHeaders(document.getElementById(tableId),fields)}
function goLive(p){livePage=p;renderLive()}
function renderLive(){discoveryHighlight('liveDiscoveryTable',liveFilters,document.getElementById('liveDiscoverySort').value);const q=(document.getElementById('liveDiscoverySearch').value||'').toLowerCase(),key=document.getElementById('liveDiscoverySort').value,desc=document.getElementById('liveDiscoverySortDir').value==='desc';let a=liveResults.filter(c=>(showExcluded||(c.workflow_status||'unreviewed')!=='excluded')&&(!q||`${c.channel_title||''} ${c.channel_id||''} ${c.country_resolved||c.country_api||''} ${c.title||''}`.toLowerCase().includes(q))&&chain(c,liveFilters,liveCond));a.sort((x,y)=>{const av=liveSortValue(x,key),bv=liveSortValue(y,key),z=typeof av==='number'&&typeof bv==='number'?av-bv:String(av).localeCompare(String(bv),'zh-CN',{numeric:true,sensitivity:'base'});return desc?-z:z});const pages=Math.max(1,Math.ceil(a.length/liveSize));livePage=Math.max(1,Math.min(pages,livePage));const start=(livePage-1)*liveSize,part=a.slice(start,start+liveSize);document.getElementById('liveDiscoveryRows').innerHTML=part.map(row).join('')||(liveResults.length?'<tr><td colspan="11" class="empty">没有符合筛选条件的结果</td></tr>':'<tr><td colspan="11" class="empty">尚未执行搜索</td></tr>');document.getElementById('liveDiscoverySummary').textContent=`共 ${a.length} 条 · 当前显示 ${a.length?start+1:0}-${Math.min(start+liveSize,a.length)}`;CDHTableTools.renderPager({page:livePage,pages,go:goLive,firstId:'liveDiscoveryFirst',prevId:'liveDiscoveryPrev',nextId:'liveDiscoveryNext',lastId:'liveDiscoveryLast',buttonsId:'liveDiscoveryPageButtons',inputId:'liveDiscoveryPageInput',jumpId:'liveDiscoveryJump',pageInfoId:'liveDiscoveryPageInfo'});bindRows();bindCreatorChecks('#liveDiscoveryRows')}
function setupGeography(){const rg=document.getElementById('discoverRegionGroup'),cs=document.getElementById('discoverCountry'),inp=document.getElementById('discoverCountrySearch'),dl=document.getElementById('countrySuggestions');rg.innerHTML='<option value="">全部大洲/区域</option>'+(GEO.groups||[]).map(g=>`<option value="${g.id}">${g.name}</option>`).join('');dl.innerHTML=(GEO.countries||[]).flatMap(c=>[`<option value="${esc(c.name_zh)}">${c.code} · ${esc(c.name_en)}</option>`,`<option value="${c.code}">${esc(c.name_zh)} · ${esc(c.name_en)}</option>`]).join('');function fill(selected=''){const g=rg.value,arr=(GEO.countries||[]).filter(c=>!g||c.group===g);cs.innerHTML='<option value="">不限国家/地区</option>'+arr.map(c=>`<option value="${c.code}">${esc(c.name_zh)} (${c.code})</option>`).join('');if(selected&&arr.some(c=>c.code===selected))cs.value=selected}function resolve(){const q=(inp.value||'').trim().toLowerCase().replace(/[()（）]/g,' '),tokens=q.split(/\s+/).filter(Boolean);let c=(GEO.countries||[]).find(x=>[x.code.toLowerCase(),x.name_zh.toLowerCase(),x.name_en.toLowerCase()].includes(q));if(!c)c=(GEO.countries||[]).find(x=>tokens.includes(x.code.toLowerCase())||tokens.includes(x.name_zh.toLowerCase()));if(c){rg.value=c.group;fill(c.code);inp.value=c.name_zh;return c}return null}rg.onchange=()=>{fill();inp.value=''};cs.onchange=()=>{const c=countryByCode.get(cs.value);inp.value=c?c.name_zh:''};inp.onchange=resolve;inp.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();resolve()}};fill()}
function setupDiscoverTime(){const s=document.getElementById('discoverLookback'),d=document.getElementById('discoverCustomDates');s.onchange=()=>d.style.display=s.value==='custom'?'inline-flex':'none'}

function normTerm(x){return String(x||'').trim().replace(/\s+/g,' ')}
function termKey(x){return normTerm(x).toLocaleLowerCase()}
function uniqTerms(xs){const out=[],seen=new Set();for(const raw of xs||[]){const x=normTerm(raw),k=termKey(x);if(x&&!seen.has(k)){seen.add(k);out.push(x)}}return out}
function defaultPackRecord(p){const terms={},active={};for(const lang of Object.keys(QP.languages||{})){const vals=uniqTerms((p.terms||{})[lang]||[]);terms[lang]=vals;active[lang]=[...vals]}return {id:String(p.id||''),name:String(p.name_zh||p.name||p.id||'Query Pack'),description:String(p.description_zh||p.description||''),enabled:!!p.default_enabled,system:true,terms,active}}
function defaultPackById(id){return (QP.packs||[]).find(p=>String(p.id||'')===String(id||''))||null}
function freshQueryState(){const packs={},order=[];for(const p of QP.packs||[]){const rec=defaultPackRecord(p);if(!rec.id)continue;order.push(rec.id);packs[rec.id]=rec}return {schema_version:4,profile:'generic_creator_discovery_v2',order,packs}}
function normalizePackId(raw){let s=String(raw||'').trim().replace(/[^a-zA-Z0-9_.:-]+/g,'_').replace(/^_+|_+$/g,'');if(!s)s='pack';return s.slice(0,80)}
function normalizePackRecord(id,src={},fallback=null){const terms={},active={};for(const lang of Object.keys(QP.languages||{})){let vals=uniqTerms(src?.terms?.[lang]||fallback?.terms?.[lang]||[]);const allow=new Map(vals.map(x=>[termKey(x),x]));let on=uniqTerms(src?.active?.[lang]||vals).map(x=>allow.get(termKey(x))).filter(Boolean);terms[lang]=vals;active[lang]=on}return {id,name:String(src.name||fallback?.name||id).trim()||id,description:String(src.description||fallback?.description||''),enabled:!!src.enabled,system:!!fallback,terms,active}}
function mergeQueryState(saved){const fresh=freshQueryState();if(!saved||typeof saved!=='object'||!saved.packs)return fresh;if(Number(saved.schema_version||0)>=4&&saved.profile==='generic_creator_discovery_v2'){
 const packs={},order=[],raw=saved.packs||{},requested=Array.isArray(saved.order)?saved.order:Object.keys(raw);for(const rid of [...requested,...Object.keys(raw).filter(x=>!requested.includes(x))]){const id=normalizePackId(rid);if(!id||packs[id]||!raw[rid])continue;const def=defaultPackById(id),fb=def?defaultPackRecord(def):null;packs[id]=normalizePackRecord(id,raw[rid],fb);order.push(id)}return {schema_version:4,profile:'generic_creator_discovery_v2',order,packs}}
 // v3 -> v4: preserve fixed-pack terms and enabled state instead of resetting user edits.
 for(const id of fresh.order){const old=saved.packs?.[id];if(!old)continue;const rec=fresh.packs[id];rec.enabled=!!old.enabled;for(const lang of Object.keys(QP.languages||{})){if(Array.isArray(old.terms?.[lang]))rec.terms[lang]=uniqTerms(old.terms[lang]);const allow=new Map(rec.terms[lang].map(x=>[termKey(x),x]));rec.active[lang]=Array.isArray(old.active?.[lang])?uniqTerms(old.active[lang]).map(x=>allow.get(termKey(x))).filter(Boolean):[...rec.terms[lang]]}}return fresh}
function loadQueryState(){let saved=null;try{saved=JSON.parse(localStorage.getItem(QP_STORE)||'null');if(!saved){saved=JSON.parse(localStorage.getItem(QP_PREV_STORE)||'null')}}catch(e){}return mergeQueryState(saved)}
function queryProfileValue(){return {schema_version:4,profile:'generic_creator_discovery_v2',language:currentQueryLang(),order:[...(queryState?.order||[])],packs:queryState?.packs||{}}}
function saveQueryState(){localStorage.setItem(QP_STORE,JSON.stringify(queryState));try{localStorage.setItem(QP_LANG_STORE,currentQueryLang())}catch(e){}if(interactive&&queryDbReady){clearTimeout(querySaveTimer);querySaveTimer=setTimeout(()=>post('/api/settings/set',{key:'query_profile',value:queryProfileValue()}).catch(()=>{}),180)}}
async function hydrateQueryProfile(){if(!interactive)return;const x=await post('/api/settings/get',{key:'query_profile'});const v=x.value||null;queryState=mergeQueryState(v);const lang=document.getElementById('queryLanguage');if(v?.language&&QP.languages?.[v.language])lang.value=v.language;localStorage.setItem(QP_STORE,JSON.stringify(queryState));localStorage.setItem(QP_LANG_STORE,lang.value);if(Number(v?.schema_version||0)<4||v?.profile!=='generic_creator_discovery_v2')await post('/api/settings/set',{key:'query_profile',value:queryProfileValue()});queryDbReady=true;renderQueryPacks();updateQueryPreview();const st=document.getElementById('queryProfileStatus');if(st)st.textContent='Query Pack 组、顺序与多语言词库已按当前 Workspace 保存到本地 SQLite'}
function currentQueryLang(){return document.getElementById('queryLanguage').value||QP.default_language||'en'}
function activeSet(st,lang){return new Set((st?.active?.[lang]||[]).map(termKey))}
function packList(){return (queryState?.order||[]).map(id=>queryState.packs?.[id]).filter(Boolean)}
function buildExpandedQueries(base){const q=normTerm(base),out=[],seen=new Set();function add(x){x=normTerm(x);const k=termKey(x);if(x&&!seen.has(k)){seen.add(k);out.push(x)}}add(q);const lang=currentQueryLang();for(const st of packList()){if(!st?.enabled)continue;const active=activeSet(st,lang);for(const term of st.terms?.[lang]||[]){if(active.has(termKey(term)))add(`${q} ${term}`)}}return out.slice(0,Number(QP.max_queries_per_search||80))}
function queryTermChip(packId,term,index,checked){return `<span class="qe-term ${checked?'':'inactive'}"><label title="勾选后本次搜索使用该扩展词"><input type="checkbox" data-qe-term-toggle="${esc(packId)}" data-qe-index="${index}" ${checked?'checked':''}> <span>${esc(term)}</span></label><button type="button" data-qe-remove="${esc(packId)}" data-qe-index="${index}" title="从当前语言词库删除">×</button></span>`}
function uniquePackId(seed='pack'){let base=normalizePackId(seed),id=base,n=2;while(queryState.packs[id])id=`${base}_${n++}`;return id}
function addPack(){const id=uniquePackId('custom_'+Date.now().toString(36)),terms={},active={};for(const lang of Object.keys(QP.languages||{})){terms[lang]=[];active[lang]=[]}queryState.packs[id]={id,name:'新建扩展组',description:'',enabled:false,system:false,terms,active};queryState.order.push(id);saveQueryState();renderQueryPacks();updateQueryPreview();setTimeout(()=>document.querySelector(`[data-qe-edit="${CSS.escape(id)}"]`)?.click(),0)}
function duplicatePack(id){const src=queryState.packs[id];if(!src)return;const nid=uniquePackId(id+'_copy'),copy=JSON.parse(JSON.stringify(src));copy.id=nid;copy.name=(src.name||id)+' · 副本';copy.system=false;queryState.packs[nid]=copy;const at=Math.max(0,queryState.order.indexOf(id));queryState.order.splice(at+1,0,nid);saveQueryState();renderQueryPacks();updateQueryPreview()}
function deletePack(id){const p=queryState.packs[id];if(!p)return;if(!confirm(`删除 Query Pack「${p.name||id}」？组内多语言词库也会从当前 Workspace 配置中删除。`))return;delete queryState.packs[id];queryState.order=queryState.order.filter(x=>x!==id);saveQueryState();renderQueryPacks();updateQueryPreview()}
function movePack(id,delta){const i=queryState.order.indexOf(id),j=i+delta;if(i<0||j<0||j>=queryState.order.length)return;[queryState.order[i],queryState.order[j]]=[queryState.order[j],queryState.order[i]];saveQueryState();renderQueryPacks();updateQueryPreview()}
function resetPack(id){const def=defaultPackById(id);if(!def)return alert('该组为自定义组，没有系统默认值。');if(!confirm(`恢复「${queryState.packs[id]?.name||id}」的系统默认名称、说明、启用状态和全部语言词库？`))return;queryState.packs[id]=defaultPackRecord(def);saveQueryState();renderQueryPacks();updateQueryPreview()}
