function savedRow(h){const country=h.library_country||h.country_resolved||h.country_api||'—',subs=h.library_subscribers||h.subscribers,local=h.library_channel_id?'已在博主库':'仅发现记录',score=h.pre_score==null?null:Number(h.pre_score),cu=`https://www.youtube.com/channel/${encodeURIComponent(h.channel_id||'')}`,vu=`https://www.youtube.com/watch?v=${encodeURIComponent(h.video_id||'')}`;return `<tr data-cid="${esc(h.channel_id||'')}"><td class="entity-cell"><a class="link-ext" target="_blank" rel="noopener" href="${cu}"><b>${esc(h.channel_title||h.channel_id)}</b></a></td><td>${fmt(subs)}</td><td>${esc(country)}</td><td class="video-title-cell"><a class="link-ext" target="_blank" rel="noopener" href="${vu}" title="${esc(h.title||'')}">${esc(h.title||'')}</a></td><td>${fmt(h.views)}</td><td>${score==null?'—':score.toFixed(1)} ${tierPill(h.opportunity_tier)}</td><td>${local}<div class="small">${esc(h.workflow_label||'未处理')}</div></td><td>${esc((h.found_at||'').slice(0,10))}</td></tr>`}
