function renderStaticSet(rows,conds,prefix,page,size,sortKey,sortDir){const q=(document.getElementById(`${prefix}Search`).value||'').toLowerCase(),desc=sortDir==='desc';let a=rows.filter(r=>(!q||(r.dataset.search||'').toLowerCase().includes(q))&&chain(r,conds,staticCond));const map=prefix==='savedCreator'?{score:'score',found:'found',subs:'subs',views:'views',coverage:'coverage',hits:'hits',repeat:'repeat',title:'title'}:{score:'score',found:'found',subs:'subs',views:'views',title:'title'},attr=map[sortKey]||'score';a.sort((x,y)=>{const av=x.dataset[attr]||'',bv=y.dataset[attr]||'',num=['score','subs','views','coverage','hits','repeat'].includes(sortKey),z=num?Number(av)-Number(bv):String(av).localeCompare(String(bv),'zh-CN',{numeric:true});return desc?-z:z});const pages=Math.max(1,Math.ceil(a.length/size)),safePage=Math.max(1,Math.min(pages,page)),start=(safePage-1)*size,shown=new Set(a.slice(start,start+size)),tbody=document.getElementById(`${prefix}Rows`);rows.forEach(r=>r.style.display=shown.has(r)?'':'none');a.forEach(r=>tbody.appendChild(r));document.getElementById(`${prefix}Summary`).textContent=`共 ${a.length} 条 · 当前显示 ${a.length?start+1:0}-${Math.min(start+size,a.length)}`;return {a,pages,page:safePage}}
